h=r("src/index.html")
h=h.replace("/*__LIVE_CSS__*/",r("src/live.css")).replace("/*__EDIT_CSS__*/",r("src/editor.css")).replace("/*__EDIT_JS__*/",r("src/editor.js")).replace("/*__REDE_JS__*/",r("src/rede.js")).replace("/*__CEL_JS__*/",r("src/celular.js")).replace("/*__CEL_CSS__*/",r("src/celular.css")).replace("/*__LIVE_JS__*/",r("src/live.js")).replace("/*__QR__*/",r("src/qrcode.js")).replace("/*__REL_CSS__*/",r("src/relat.css")).replace("/*__REF_CSS__*/",r("src/reforco.css")).replace("/*__REF_JS__*/",r("src/reforco.js")).replace("/*__PES_CSS__*/",r("src/pessoas.css")).replace("/*__PES_JS__*/",r("src/pessoas.js")).replace("/*__INT_JS__*/",r("src/integra.js")).replace("/*__INT_CSS__*/",r("src/integra.css")).replace("/*__V10_JS__*/",r("src/v10.js")).replace("/*__V10_CSS__*/",r("src/v10.css")).replace("/*__V11_CSS__*/",r("src/v11.css")).replace("/*__V11_JS__*/",r("src/v11.js")).replace("/*__V12_CSS__*/",r("src/v12.css")).replace("/*__V12_JS__*/",r("src/v12.js")).replace("/*__PDF_JS__*/",r("src/pdf.js").replace("__HELV__",r("helv.json").strip())).replace("/*__REL_JS__*/",r("src/relat.js")).replace("__MODELOS__",r("modelos.json"))
import os; os.makedirs(d+"/dist", exist_ok=True)
open(d+"/dist/index.html","w",encoding="utf8").write(h)
